def xml(self, attribs = None,elements = None, skipchildren = False):
        """Serialises the FoLiA element to XML, by returning an XML Element (in lxml.etree) for this element and all its children. For string output, consider the xmlstring() method instead."""
        if attribs is None:
            attribs = {}
        if elements is None:
            elements = []
        # create the element
        element = etree.Element(self.tag, attrib = attribs)
        # add the children
        for child in self.children:
            if not skipchildren or not isinstance(child, FoLiAElement):
                element.append(child.xml())
        # add the text
        if self.text:
            element.text = self.text
        # return the element
        return element

